import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from decimal import Decimal, ROUND_HALF_UP
BASE='http://localhost:8080'
token=None
stats={}
def request(path, auth=True):
    global token
    while True:
        if auth and token is None:
            token=[REDACTED_SECRET]'/token',False)['token']
        req=urllib.request.Request(BASE+path,method='GET' if auth else 'POST',headers={'Authorization':'Bearer '+token} if auth else {})
        try:
            with urllib.request.urlopen(req,timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            stats[str(e.code)]=stats.get(str(e.code),0)+1
            body=e.read().decode()
            if e.code==401 and auth:
                token=None
                continue
            delay=e.headers.get('Retry-After')
            if delay:
                try: wait=float(delay)
                except ValueError: wait=max(0,(parsedate_to_datetime(delay)-datetime.now(timezone.utc)).total_seconds())
            else:
                wait=1
                try:
                    b=json.loads(body)
                    wait=float(b.get('retry_after',1))
                except (ValueError,TypeError): pass
            print(f'Retrying {path}: HTTP {e.code}; waiting {wait}s; {body[:150]}',flush=True)
            time.sleep(max(0,wait))
        except (OSError,ValueError) as e:
            print(f'Retrying {path}: {e}',flush=True)
            time.sleep(1)
orders={}; duplicates=0; pages=[]; path='/orders?page=1'
while path is not None:
    assert path not in [p['path'] for p in pages], 'pagination loop'
    data=request(path)
    pages.append({'path':path,'data':data})
    for o in data['items']:
        if o['id'] in orders:
            assert orders[o['id']]==o, 'conflicting duplicate'
            duplicates+=1
        else: orders[o['id']]=o
    print(f\"Page {data['page']}/{data['total_pages']}: {len(orders)} unique, {duplicates} duplicates\",flush=True)
    path=data['next']
assert [p['data']['page'] for p in pages]==list(range(1,pages[-1]['data']['total_pages']+1))
start=datetime(2025,3,1,tzinfo=timezone.utc); end=datetime(2025,6,1,tzinfo=timezone.utc)
qualified=[]; boundary=[]
for o in orders.values():
    dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00'))
    assert dt.tzinfo is not None
    inside=start<=dt.astimezone(timezone.utc)<end
    local_inside='2025-03-01'<=o['placed_at'][:10]<='2025-05-31'
    if inside"'!=local_inside: boundary.append({'"'order':o,'included':inside})
    if o['status']=='shipped' and inside: qualified.append(o)
customers={}; regions=dict.fromkeys(['north','south','east','west'],0)
for o in qualified:
    cid=o['customer_id']
    if cid not in customers:
        customers[cid]=request('/customers/'+cid)
        if len(customers)%10==0: print(f'Customers fetched: {len(customers)}',flush=True)
    c=customers[cid]
    assert c['id']==cid and type(c['discount_pct']) is int and 0<=c['discount_pct']<=100
    numerator=o['amount_cents']*(100-c['discount_pct'])
    cents=(numerator+50)//100
    assert cents==int((Decimal(o['amount_cents'])*(100-c['discount_pct'])/100).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
    regions[c['region']]+=cents
result={'total_cents':sum(regions.values()),'order_count':len(qualified),'duplicates_skipped':duplicates,'by_region':regions}
with open('/tmp/reconciliation_audit.json','w') as f: json.dump({'pages':pages,'customers':customers,'boundary':boundary,'stats':stats},f)
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps(result),flush=True)
print('Boundary date differences: '+json.dumps(boundary),flush=True)
print('Request retries: '+json.dumps(stats),flush=True)
